// Clean Prompt: one item per segment; segment name comes from Wait3 (the agent output only has "output")
const items = $input.all();
const segs = $('Wait3').all();
const plain = (s, n) => String(s ?? '').replace(/\r?\n/g, ' ').replace(/[*#`_>\[\]{}\\]/g, ' ').replace(/"/g, "'").replace(/\s+/g, ' ').trim().slice(0, n);

return items.map((item, i) => {
  const seg = (segs[i] && segs[i].json && segs[i].json.segment) || {};
  const segmentName = plain(seg.name, 60) || 'Style';
  let prompt = plain(item.json.output, 1000);

  // AI step failed or returned nothing: build a plain prompt from the segment itself
  const aiPrompt = prompt.length >= 40;
  if (!aiPrompt) {
    const join = (v, n) => (Array.isArray(v) ? v : []).slice(0, n).map((x) => plain(x, 40)).filter(Boolean).join(', ');
    const room = join(seg.target_rooms, 1) || 'living room';
    prompt = `A ${room} with a ${segmentName} rug as the focal point, ${join(seg.visual_characteristics, 3)}, colors ${join(seg.color_palette, 3)}, materials ${join(seg.typical_materials, 2)}`;
    prompt = plain(prompt, 600);
  }

  if (!prompt.toLowerCase().includes('professional')) prompt = 'Professional interior design photography, ' + prompt;
  if (!prompt.toLowerCase().includes('high quality')) prompt += ', high quality, detailed textures, natural lighting';

  return { json: { prompt, segmentName, promptSource: aiPrompt ? 'ai' : 'segment_fallback' } };
});

// Extract the base64 image from the Cloudflare Workers AI JSON response and carry the segment's evidence with it
const items = $input.all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];

  // works whether "Full Response" is on or off
  const body = item.json.result ? item.json : (item.json.body || {});
  const base64 = body.result && body.result.image ? body.result.image : '';

  // the n8n position of this item in the node before (pairedItem), falling back to its place in the list
  const idx = item.pairedItem && item.pairedItem.item !== undefined ? item.pairedItem.item : i;

  // segment name from Clean Prompt; evidence fields from Wait3 (the saved segment), both matched by position
  let segmentName = item.json.segmentName || 'Style';
  try {
    const src = $('Clean Prompt').all()[idx]; // use YOUR node's exact name
    if (src && src.json.segmentName) segmentName = src.json.segmentName;
  } catch (e) { /* keep the fallback */ }

  let seg = {};
  try {
    const s = $('Wait3').all()[idx];
    if (s && s.json && s.json.segment) seg = s.json.segment;
  } catch (e) { /* no evidence available */ }

  const evidence = {
    description: seg.description || '',
    support_level: seg.support_level || 'unverified',
    confidence: seg.confidence || 'low',
    weakest_attribute: seg.weakest_attribute || null,
    trend_signals: Array.isArray(seg.trend_signals) ? seg.trend_signals : [],
  };

  if (base64) {
    results.push({
      json: { segmentName, base64Image: base64, mimeType: 'image/jpeg', hasImage: true, ...evidence },
    });
  } else {
    results.push({
      json: { segmentName, base64Image: null, mimeType: null, hasImage: false, error: 'No image in response', ...evidence },
    });
  }
}

return results;
